using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ThornEffect", menuName = "Data/Battle/Effects/Thorn Effect")]
public class ThornEffect : Effect
{
	[Header("Battle Action")]
	[SerializeField]
	protected BattleAction battleAction;

	[SerializeField]
	private bool corruptedThorn;

	public BattleAction BattleAction => battleAction;

	public override int ActivateEffectWithSource(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (effectOwner != source)
		{
			CorruptionStats component = source.GetComponent<CorruptionStats>();
			if (corruptedThorn)
			{
				component.Corrupt(effectAmount, null);
			}
			else
			{
				component.Purify(effectAmount, null);
			}
		}
		return effectAmount;
	}
}
